      "evidence": ["src/main/java/org/apache/commons/io/input/BufferedFileChannelInputStream.java", "src/main/java/org/apache/commons/io/input/BOMInputStream.java", "src/main/java/org/apache/commons/io/input/ObservableInputStream.java", "src/main/java/org/apache/commons/io/input/CloseShieldInputStream.java"]
