      "evidence": ["src/main/java/org/apache/commons/io/filefilter/WildcardFileFilter.java", "src/main/java/org/apache/commons/io/filefilter/SizeFileFilter.java", "src/main/java/org/apache/commons/io/comparator/NameFileComparator.java", "src/main/java/org/apache/commons/io/comparator/SizeFileComparator.java"]
